class Solution {
public:
    bool canPlaceFlowers(std::vector<int>& flowerbed, int n) {
        for (int i = 0; i < (int)flowerbed.size() && n > 0; ++i) {
            if (flowerbed[i] == 0 &&
                (i == 0 || flowerbed[i - 1] == 0) &&
                (i + 1 == (int)flowerbed.size() || flowerbed[i + 1] == 0)) {
                flowerbed[i] = 1;
                --n;
            }
        }
        return n <= 0;
    }
};
